package com.bank.batch;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ReverseKGroupDemo {

    private static final Logger log = Logger.getLogger(ReverseKGroupDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Chain: T1 → T2 → T3 → T4 → T5
        TxnNode head = chain("T1", "T2", "T3", "T4", "T5");

        BatchReverser reverser = new BatchReverser();
        TxnNode result = reverser.reverseInGroups(head, 2);

        // Expect: T2 → T1 → T4 → T3 → T5 (last single node unchanged)
        log.info(() -> "Reordered chain: " + render(result));
    }

    private static TxnNode chain(String... ids) {
        TxnNode dummy = new TxnNode("");
        TxnNode cur = dummy;
        for (String id : ids) { cur.next = new TxnNode(id); cur = cur.next; }
        return dummy.next;
    }

    private static String render(TxnNode head) {
        StringBuilder sb = new StringBuilder();
        for (TxnNode n = head; n != null; n = n.next) {
            sb.append(n.id);
            if (n.next != null) sb.append(" → ");
        }
        return sb.toString();
    }
}

