class TxnNode {
    final String id;
    TxnNode next;
    TxnNode(String id) { this.id = id; }
}

// ─── Would be in service/BatchReverser.java in a real project ───
class BatchReverser {

    private static final Logger log = Logger.getLogger(BatchReverser.class.getName());

    TxnNode reverseInGroups(TxnNode head, int k) {
        TxnNode dummy = new TxnNode("");       // stable handle before head
        dummy.next = head;
        TxnNode beforeGroup = dummy;           // node just before current group

        while (true) {
            // Step 1: verify k nodes remain from beforeGroup.next.
            TxnNode check = beforeGroup;
            for (int i = 0; i < k && check != null; i++) check = check.next;
            if (check == null) break;          // fewer than k left → leave as is

            // Step 2: reverse exactly k nodes.
            TxnNode prev = null;
            TxnNode cur = beforeGroup.next;
            TxnNode groupTail = cur;           // original first node → becomes tail
            for (int i = 0; i < k; i++) {
                TxnNode nxt = cur.next;
                cur.next = prev;               // flip pointer
                prev = cur;
                cur = nxt;
            }
            // Step 3: reconnect the three links.
            beforeGroup.next = prev;           // before → new group front
            groupTail.next = cur;              // group tail → rest of list
            beforeGroup = groupTail;           // advance for next group
            log.fine(() -> "  reversed a group of " + k);
        }
        return dummy.next;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
